```python
import numpy as np
import time

def mandelbrot(h, w, max_iter=100):
    # Create a grid of complex numbers
    y, x = np.ogrid[-1.5:1.5:h*1j, -2:1:w*1j]
    c = x + y*1j
    z = c
    divtime = max_iter + np.zeros(z.shape, dtype=int)

    for i in range(max_iter):
        z = z**2 + c
        diverge = z*np.conj(z) > 2**2            # find points that diverge
        div_now = diverge & (divtime == max_iter)  # find points diverging right now
        divtime[div_now] = i                    # note time of divergence
        z[diverge] = 2                          # prevent overflow

    return divtime

if __name__ == "__main__":
    start = time.time()
    mandelbrot(1000, 1000)
    print(f"Python执行时间: {time.time() - start:.4f} seconds")
```

### The Rust Implementation (Multi-threaded)
Rust allows us to use true parallelism. I am using the `rayon` crate, which is the industry standard for converting sequential iterators into parallel ones.

**Cargo.toml dependencies:**
```toml
[dependencies]
rayon = "1.8"
```

**main.rs:**
```rust
use rayon::prelude::*;

fn mandelbrot(h: usize, w: usize, max_iter: u32) -> Vec<Vec<u32>> {
    (0..h).into_par_iter().map(|py| {
        let mut row = Vec::with_capacity(w);
        for px in 0..w {
            let x0 = -2.0 + (px as f64 / w as f64) * 3.0;
            let y0 = -1.5 + (py as f64 / h as f64) * 3.0;
            let mut x = 0.0;
            let mut y = 0.0;
            let mut iteration = 0;
            while x*x + y*y <= 4.0 && iteration < max_iter {
                let xtemp = x*x - y*y + x0;
                y = 2.0*x*y + y0;
                x = xtemp;
                iteration += 1;
            }
            row.push(iteration);
        }
        row
    }).collect()
}

fn main() {
    let start = std::time::Instant::now();
    mandelbrot(1000, 1000, 100);
    println!("Rust execution time: {:.4} seconds", start.elapsed().as_secs_f64());
}
```

