use std::time::Instant;

fn mandelbrot(c_re: f64, c_im: f64, max_iter: u32) -> u32 {
    let mut z_re = 0.0;
    let mut z_im = 0.0;
    for i in 0..max_iter {
        let re2 = z_re * z_re;
        let im2 = z_im * z_im;
        if re2 + im2 > 4.0 {
            return i;
        }
        z_im = 2.0 * z_re * z_im + c_im;
        z_re = re2 - im2 + c_re;
    }
    max_iter
}

fn main() {
