### The Python Implementation
Python is an interpreted language. For a task like this, which requires millions of small mathematical operations in a loop, Python suffers from "interpreter overhead."

```python
# mandelbrot.py
import time

def generate_mandelbrot(width, height, max_iter):
    # Create a 2D list (grid)
    result = [[0 for _ in range(width)] for _ in range(height)]

    for y in range(height):
        for x in range(width):
            # Map pixel to complex plane
            zx = 0.0
            zy = 0.0
            cx = (x - width / 1.5) * 4.0 / width
            cy = (y - height / 2.0) * 4.0 / height

            iteration = 0
            while zx*zx + zy*zy <= 4.0 and iteration < max_iter:
                temp = zx*zx - zy*zy + cx
                zy = 2.0*zx*zy + cy
                zx = temp
                iteration += 1

            result[y][x] = iteration
    return result

if __name__ == "__main__":
    W, H, ITER = 1000, 1000, 100
    start = time.time()
    generate_mandelbrot(W, H, ITER)
    print(f"Python took: {time.time() - start:.4f} seconds")
```

